ENDPOINTS = []

def group(name, source, rows, status='Parity'):
    for line in rows.strip().splitlines():
        if not line.strip(): continue
        method, path, purpose, auth, inputs, response, errors = line.split(' | ')
        ENDPOINTS.append(dict(domain=name, method=method, path='/v1'+path,
            purpose=purpose, authorization=auth, request=inputs,
            success=response, additional_errors=errors, status=status, source=source))

# Paths and DTOs are recommendations. Parity labels the existing business capability,
# never the existence of a Node.js route. Common contracts are rendered below.
